// Auto-generated by the per-command split.
const os = require('os');
const dns = require('dns').promises;
const tls = require('tls');
const crypto = require('crypto');
const moment = require('moment-timezone');
const fetch = require('node-fetch');
const ytSearch = require('yt-search');
const { formatUptime, formatUptimeVerbose, extractNumber, progressBar } = require('../lib/helpers');

function buildCommand() {
  const __args = [['video'], 'Music', 'Search for a video on YouTube', async ({ sock, from, msg, args }) => {
  const query = args.join(' ');
  if (!query) return sock.sendMessage(from, { text: 'Usage: .video funny cats' }, { quoted: msg });
  try {
    const { videos } = await ytSearch(query);
    const top = videos[0];
    if (!top) return sock.sendMessage(from, { text: 'No results found.' }, { quoted: msg });
    await sock.sendMessage(from, {
      image: { url: top.thumbnail },
      caption: `🎬 *${top.title}*\nDuration: ${top.timestamp}\nViews: ${top.views.toLocaleString()}\nLink: ${top.url}\n\n_Note: this finds the video — full video download needs a downloader API to be added later._`
    }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Search failed, try again.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
